type MyClass<T> = setmetatable<{ _t: T }, typeof(MyClass)>

type MyFunction<T> = (class: MyClass<T>) -> () | {
    fn: ((class: MyClass<T>) -> ())?,
}

function MyClass.__index.call<T>(self: MyClass<T>, f: MyFunction<T>): ()
    if type(f) == "function" then
        f(self)
    elseif f.fn then
        const thevalue = f.fn
        local _ = thevalue
        f.fn(self)
    end
end

